// Aggregate prices per pesticide
const items = $input.all();

const priceIndex = {
  generated_at: new Date().toISOString(),
  date: new Date().toISOString().split('T')[0],
  region: 'Punjab',
  total_pesticides: items.length,
  pesticides: []
};

for (const item of items) {
  const p = item.json;
  const prices = p.prices || [];
  const priceValues = prices.map(pr => pr.price || 0).filter(v => v > 0);

  const avg = priceValues.length > 0 
    ? Math.round(priceValues.reduce((a, b) => a + b, 0) / priceValues.length) 
    : 0;
  const min = priceValues.length > 0 ? Math.min(...priceValues) : 0;
  const max = priceValues.length > 0 ? Math.max(...priceValues) : 0;

  // Find cheapest vendor
  const cheapest = prices.sort((a, b) => (a.price || 999999) - (b.price || 999999))[0] || {};

  priceIndex.pesticides.push({
    name: p.name,
    hindi_name: p.hindi_name,
    category: p.category,
    target_diseases: p.target_diseases,
    price_stats: {
      average: avg,
      minimum: min,
      maximum: max,
      vendors_compared: priceValues.length,
      currency: 'INR'
    },
    cheapest_vendor: {
      name: cheapest.vendor || 'N/A',
      city: cheapest.city || '',
      price: cheapest.price || 0,
      pack_size: cheapest.pack_size || ''
    }
  });
}

console.log('[Krishi-Sarthi PRICES]', JSON.stringify({
  date: priceIndex.date,
  pesticides: priceIndex.total_pesticides,
  region: priceIndex.region
}));

return [{ json: priceIndex }];
